    <script>
    document.addEventListener('DOMContentLoaded', () => {
        const yamlText = document.getElementById('yaml-data-source').textContent;
        if (!yamlText.trim()) { console.error("YAML data source is empty."); return; }
        const data = jsyaml.load(yamlText).echo_chamber_feed;
        if (!data) { console.error("Failed to parse YAML or find 'echo_chamber_feed' root key."); return; }

        function renderViewerProfile(profile) {
            if (!profile) return;
            document.getElementById('viewer-avatar-sm').textContent = profile.avatar_char || '';
            document.getElementById('viewer-avatar-lg').textContent = profile.avatar_char || '';
            document.getElementById('viewer-name-lg').textContent = profile.name || '未知用户';
            document.getElementById('viewer-posts-count').textContent = profile.posts_count ?? 0;
            document.getElementById('viewer-followers-count').textContent = profile.followers_count ?? 0;
            document.getElementById('viewer-following-count').textContent = profile.following_count ?? 0;
        }

        function createPostCardHTML(post) {
            const likedClass = post.stats.is_liked_by_viewer ? 'liked' : '';
            const avatarStyle = `background: ${post.user.avatar_bg};`;
            const tagsHTML = (post.tags || []).map(tag => `<span class="tag-item" data-action="search-tag" data-tag="${tag}">#${tag}</span>`).join('');
            const npcCommentsData = JSON.stringify(post.npc_comments || []);

            return `
            <article class="post-card" data-npc-comments='${npcCommentsData}'>
                <header class="post-header" data-action="view-profile" data-username="${post.user.name}">
                    <div class="post-avatar" style="${avatarStyle}">${post.user.avatar_icon}</div>
                    <div class="post-user-info">
                        <span class="post-user-name">${post.user.name}</span>
                        <span class="post-user-handle">${post.user.handle}</span>
                    </div>
                </header>
                <p class="post-body">${post.body}</p>
                <div class="post-tags">${tagsHTML}</div>
                ${post.image_caption ? `<figure class="post-photo"><figcaption>${post.image_caption}</figcaption></figure>` : ''}
                <footer class="post-footer">
                    <button type="button" class="footer-action" data-action="comment-post"><svg viewBox="0 0 24 24"><path d="M14.046 2.242l-4.148-.01h-.002c-4.374 0-7.8 3.427-7.8 7.802 0 4.098 3.186 7.206 7.465 7.37v3.828c0 .108.044.286.12.403.142.225.384.347.632.347.138 0 .277-.038.402-.118.264-.168 6.473-4.14 8.088-5.506 1.902-1.61 3.04-3.97 3.043-6.312v-.017c-.006-4.367-3.43-7.787-7.8-7.788zm3.787 12.972c-1.134.96-4.862 3.405-6.772 4.643V16.67c.615.033 1.22.048 1.81.048 3.456 0 6.262-2.806 6.262-6.262 0-1.556-.56-2.96-1.5-4.064 1.248 1.39 1.953 3.13 1.953 5.013v.002c0 1.96-1.022 3.85-2.755 5.16z"></path></svg><span class="comment-count-display">${post.stats.comments}</span></button>
                    <button type="button" class="footer-action ${likedClass}" data-action="like"><svg viewBox="0 0 24 24"><path d="M12 21.638h-.014C9.403 21.59 1.95 14.856 1.95 8.478c0-3.064 2.525-5.754 5.403-5.754 2.29 0 3.83 1.58 4.646 2.73.814-1.148 2.354-2.73 4.645-2.73 2.88 0 5.404 2.69 5.404 5.755 0 6.376-7.454 13.11-10.037 13.157H12z"></path></svg><span class="like-count">${post.stats.likes}</span></button>
                </footer>
                <div class="comment-section"></div>
            </article>`;
        }

        function renderPostStream(posts) {
            const postStreamContainer = document.getElementById('post-stream');
            if (!postStreamContainer) return;
            postStreamContainer.innerHTML = (posts || []).map(createPostCardHTML).join('');
        }

        function sendCommand(messageText) {
            const command = `/send ${messageText} | /trigger await=true`;
            if (typeof triggerSlash === 'function') {
                try { triggerSlash(command); console.log(`Command sent: ${command}`); }
                catch (e) { console.error("指令发送失败:", e); alert(`指令自动发送失败: ${messageText}`); }
            } else { console.error("triggerSlash not found."); alert(`无法自动发送: ${messageText}`); }
        }

        function generateNpcComments(postCard) {
            const commentSection = postCard.querySelector('.comment-section');
            const commentsData = JSON.parse(postCard.dataset.npcComments || '[]');

            let npcCommentHTML = commentsData.map(comment =>
                `<div class="comment-item">
                    <div class="comment-avatar" data-action="view-commenter-profile" data-username="${comment.author}">${comment.avatar}</div>
                    <div class="comment-content">
                        <div class="comment-user-info-container">
                            <span class="comment-user-name" data-action="view-commenter-profile" data-username="${comment.author}">${comment.author}</span>
                            <button class="comment-reply-btn" data-action="reply-to-comment" data-username="${comment.author}">回复</button>
                        </div>
                        <span class="comment-text">${comment.text}</span>
                    </div>
                </div>`
            ).join('');

            const inputAreaHTML = `<div class="comment-input-area"><textarea class="comment-input" placeholder="添加你的评论…" rows="1"></textarea><button type="button" class="comment-send-btn" data-action="send-comment">发送</button></div>`;
            commentSection.innerHTML = `<div class="comments-list">${npcCommentHTML}</div>` + inputAreaHTML;
        }

        function setupStaticListeners() {
            document.getElementById('refresh-btn').onclick = () => sendCommand('刷新首页');
            document.getElementById('search-btn').onclick = () => {
                const keyword = prompt('请输入搜索关键词：', '');
                if (keyword && keyword.trim() !== '') sendCommand(`搜索：${keyword.trim()}`);
            };
            const profileModal = document.getElementById('profile-modal');
            document.getElementById('profile-avatar-btn').onclick = () => profileModal.classList.remove('hidden');
            profileModal.querySelector('.close-modal-btn').onclick = () => profileModal.classList.add('hidden');
            profileModal.addEventListener('click', (event) => {
                if (event.target === profileModal) profileModal.classList.add('hidden');
                if (event.target.closest('[data-action="view-my-posts"]')) {
                    sendCommand('查看我的动态');
                    profileModal.classList.add('hidden');
                }
            });
        }

        function setupPostStreamListeners() {
            const postStream = document.getElementById('post-stream');
            if (!postStream) return;
            postStream.addEventListener('click', (event) => {
                const button = event.target.closest('[data-action]');
                if (!button) return;
                const action = button.dataset.action;
                const postCard = button.closest('.post-card');
                let textarea, commentSection, isVisible;

                switch (action) {
                    case 'view-profile':
                        const username = button.dataset.username;
                        if(username) sendCommand(`<查看："${username}"主页>`);
                        break;
                    case 'like':
                        button.classList.toggle('liked');
                        const countSpan = button.querySelector('.like-count');
                        let currentCount = parseInt(countSpan.textContent, 10);
                        if (isNaN(currentCount)) return;
                        countSpan.textContent = button.classList.contains('liked') ? currentCount + 1 : currentCount - 1;
                        break;
                    case 'comment-post':
                        commentSection = postCard.querySelector('.comment-section');
                        // 如果评论区还没内容，先生成
                        if (commentSection.innerHTML.trim() === '') {
                             generateNpcComments(postCard);
                        }
                        textarea = postCard.querySelector('.comment-input'); // 重新获取textarea
                        isVisible = getComputedStyle(commentSection).display !== 'none';

                        if (isVisible && textarea.placeholder === "添加你的评论…") {
                             commentSection.style.display = 'none';
                        } else {
                             commentSection.style.display = 'block';
                             textarea.placeholder = "添加你的评论…";
                             delete textarea.dataset.replyTo;
                             textarea.focus();
                        }
                        break;
                    case 'reply-to-comment':
                        commentSection = postCard.querySelector('.comment-section');
                         // 如果评论区还没内容，先生成
                        if (commentSection.innerHTML.trim() === '') {
                             generateNpcComments(postCard);
                        }
                        textarea = postCard.querySelector('.comment-input');
                        const usernameToReply = button.dataset.username;
                        commentSection.style.display = 'block';
                        textarea.placeholder = `回复 ${usernameToReply}：`;
                        textarea.dataset.replyTo = usernameToReply;
                        textarea.focus();
                        break;
                    case 'view-commenter-profile':
                        const commenterUsername = button.dataset.username;
                        if(commenterUsername) sendCommand(`<查看："${commenterUsername}"主页>`);
                        break;
                    case 'send-comment':
                        textarea = postCard.querySelector('.comment-input');
                        const commentText = textarea.value.trim();
                        if (commentText === '') return;

                        const replyToUser = textarea.dataset.replyTo;
                        const originalPosterHandle = postCard.querySelector('.post-user-handle').textContent;

                        if (replyToUser) {
                            sendCommand(`在${originalPosterHandle}的帖子下回复${replyToUser}：${commentText}`);
                        } else {
                            sendCommand(`回复 ${originalPosterHandle}：${commentText}`);
                        }

                        textarea.value = '';
                        textarea.placeholder = "添加你的评论…";
                        delete textarea.dataset.replyTo;
                        postCard.querySelector('.comment-section').style.display = 'none';
                        break;
                    case 'search-tag':
                        const tag = button.dataset.tag;
                        if(tag) sendCommand(`搜索标签：#${tag}`);
                        break;
                }
            });
        }

        renderViewerProfile(data.viewer_profile);
        renderPostStream(data.posts);
        setupStaticListeners();
        setupPostStreamListeners();
    });
    </script>
</body>
</html>
