            if (user.banner_bg) {
                if (user.banner_bg.startsWith('url(') || user.banner_bg.startsWith('linear-gradient(')) {
                     document.getElementById('profile-banner').style.backgroundImage = user.banner_bg;
                } else {
                     document.getElementById('profile-banner').style.backgroundColor = user.banner_bg;
                }
