        function renderPostStream(posts, author) {
            const postStreamContainer = document.getElementById('post-stream');
            if (!postStreamContainer || !posts) return;
            postStreamContainer.innerHTML = posts.map(post => createPostCardHTML(post, author)).join('');
        }

        // --- 3. 事件处理与交互逻辑 ---
        function sendCommand(messageText) {
            const command = `/send ${messageText} | /trigger await=true`;
            if (typeof triggerSlash === 'function') {
                try { triggerSlash(command); } catch (e) { alert(`指令发送失败: ${messageText}`); }
            } else { alert(`无法自动发送: ${messageText}`); }
        }

        function setupEventListeners(data) {
            const pageContainer = document.querySelector('.phone-screen');
            if (!pageContainer) return;

            pageContainer.addEventListener('click', (event) => {
                const button = event.target.closest('[data-action]');
                if (!button) return;

                const action = button.dataset.action;
                const postCard = button.closest('.post-card');

                let textarea, commentItem;

                switch (action) {
                    case 'back-to-home':
                        sendCommand('返回首页');
                        break;
                    case 'follow':
                        button.classList.toggle('followed');
                        button.textContent = button.classList.contains('followed') ? '已关注' : '＋ 关注';
                        break;
                    case 'message':
                        sendCommand(`私信 ${data.profile_user.handle}：`);
                        break;
                    case 'like':
                        button.classList.toggle('liked');
                        const countSpan = button.querySelector('.like-count');
                        let currentCount = parseInt(countSpan.textContent, 10);
                        if (isNaN(currentCount)) return;
                        countSpan.textContent = button.classList.contains('liked') ? currentCount + 1 : currentCount - 1;
                        break;
                    case 'comment-post':
                        const commentSection = postCard.querySelector('.comment-section');
                        textarea = postCard.querySelector('.comment-input');
                        const isVisible = getComputedStyle(commentSection).display !== 'none';

                        if (isVisible && textarea.placeholder === "添加你的评论…") {
                            commentSection.style.display = 'none';
                        } else {
                            commentSection.style.display = 'block';
                            textarea.placeholder = "添加你的评论…";
                            delete textarea.dataset.replyTo;
                            delete textarea.dataset.replyToCommentId;
                            textarea.focus();
                        }
                        break;
                    case 'reply-to-comment':
                        textarea = postCard.querySelector('.comment-input');
                        commentItem = button.closest('.comment-item');
                        const usernameToReply = button.dataset.username;
                        const commentIdToReply = commentItem.dataset.commentId;
                        postCard.querySelector('.comment-section').style.display = 'block';
                        textarea.placeholder = `回复 @${usernameToReply}：`;
                        textarea.dataset.replyTo = usernameToReply;
                        textarea.dataset.replyToCommentId = commentIdToReply;
                        textarea.focus();
                        break;
                    case 'view-commenter-profile':
                        const commenterUsername = button.dataset.username;
                        sendCommand(`<查看："${commenterUsername}"主页>`);
                        break;
                    case 'send-comment':
                        textarea = postCard.querySelector('.comment-input');
                        const commentText = textarea.value.trim();
                        if (commentText === '') return;

                        const replyToUser = textarea.dataset.replyTo;
                        const replyToComment = textarea.dataset.replyToCommentId;

                        if (replyToUser && replyToComment) {
                            sendCommand(`在 ${postCard.id} 中回复 ${replyToUser} (评论 ${replyToComment})：${commentText}`);
                        } else {
                            sendCommand(`回复 ${data.profile_user.handle} 在 ${postCard.id}：${commentText}`);
                        }

                        textarea.value = '';
                        textarea.placeholder = "添加你的评论…";
                        delete textarea.dataset.replyTo;
                        delete textarea.dataset.replyToCommentId;
                        postCard.querySelector('.comment-section').style.display = 'none';
                        break;
                }
            });
        }

        // --- 4. 执行 ---
        renderProfileHeader(data.profile_user);
        renderPostStream(data.posts, data.profile_user);
        setupEventListeners(data);
    });
    </script>
</body>
</html>
