                <div class="stat-item"><span id="viewer-followers-count" class="stat-value"></span><span class="stat-label">关注者</span></div>
                <div class="stat-item"><span id="viewer-following-count" class="stat-value"></span><span class="stat-label">正在关注</span></div>
            </div>
