    <script>
    document.addEventListener('DOMContentLoaded', () => {
        // --- 1. 数据加载与解析 ---
        const yamlText = document.getElementById('yaml-data-source').textContent;
        if (!yamlText.trim()) { console.error("YAML data source is empty."); return; }
        const data = jsyaml.load(yamlText).user_profile_page;
        if (!data) { console.error("Failed to parse YAML or find 'user_profile_page' root key."); return; }

        // --- 2. 渲染函数 ---

        function renderProfileHeader(user) {
            if (!user) return;
            document.title = `${user.name} - 回声室`;

            if (user.banner_bg) {
                if (user.banner_bg.startsWith('url(') || user.banner_bg.startsWith('linear-gradient(')) {
                     document.getElementById('profile-banner').style.backgroundImage = user.banner_bg;
                } else {
                     document.getElementById('profile-banner').style.backgroundColor = user.banner_bg;
                }
            } else {
                 document.getElementById('profile-banner').style.backgroundColor = '#EAECEF';
            }

            const avatar = document.getElementById('profile-avatar');
            avatar.textContent = user.avatar_icon || '';
            avatar.style.background = user.avatar_bg || '#ccc';

            document.getElementById('profile-name').textContent = user.name;
            document.getElementById('profile-handle').textContent = user.handle;
            document.getElementById('profile-bio').textContent = user.bio;

            const followBtn = document.getElementById('follow-btn');
            if (user.is_followed_by_viewer) {
                followBtn.classList.add('followed');
                followBtn.textContent = '已关注';
            } else {
                followBtn.classList.remove('followed');
                followBtn.textContent = '＋ 关注';
            }

            document.getElementById('followers-count').textContent = user.stats.followers;
            document.getElementById('following-count').textContent = user.stats.following;
            document.getElementById('likes-received-count').textContent = user.stats.likes_received;
        }

        function createCommentHTML(comment) {
             return `<div class="comment-item" data-comment-id="${comment.comment_id}">
                        <div class="comment-avatar" data-action="view-commenter-profile" data-username="${comment.user_name}">${comment.avatar}</div>
