                            </div>
                            <span class="comment-text">${comment.text}</span>
                         </div>
                     </div>`;
        }

        function createPostCardHTML(post, author) {
            const likedClass = post.stats.is_liked_by_viewer ? 'liked' : '';
            const commentsHTML = post.comments && post.comments.length > 0 ? post.comments.map(createCommentHTML).join('') : '';

            return `
            <article class="post-card" id="${post.id}">
                <header class="post-header">
                    <div class="post-avatar" style="background: ${author.avatar_bg};">${author.avatar_icon}</div>
                    <div class="post-user-info">
