            const continuationClass = isContinuation ? 'is-continuation' : '';
            const metaClass = isLastInGroup ? 'has-meta' : '';

            const avatarClass = isViewerSender ? 'viewer-avatar-bg' : '';
            const avatarContent = senderInfo.avatar_icon || senderInfo.avatar_char;
            const avatarStyle = !isViewerSender && senderInfo.avatar_bg ? `background: ${senderInfo.avatar_bg};` : '';

            let metaHTML = '';
            if (isLastInGroup) {
                const timestampHTML = `<span class="message-timestamp">${message.timestamp}</span>`;
                if (isViewerSender) {
                    const statusText = message.is_read ? '已读' : '送达';
                    const statusColorClass = message.is_read ? 'status-read' : 'status-sent';
                    const statusHTML = `<span class="message-status ${statusColorClass}">${statusText}</span>`;
                    metaHTML = `<div class="message-meta">${statusHTML}${timestampHTML}</div>`;
                } else {
                    metaHTML = `<div class="message-meta">${timestampHTML}</div>`;
                }
            }

            return `
            <div class="message-group ${groupClass} ${continuationClass} ${metaClass}">
                <div class="message-avatar ${avatarClass}" style="${avatarStyle}">${avatarContent}</div>
                <div class="message-content-wrapper">
                    <div class="message-bubble">${message.content}</div>
                    ${metaHTML}
                </div>
            </div>`;
        }

        function renderMessages(msgList) {
            const stream = document.getElementById('message-stream');
            if (!stream) return;
            let html = '';
            for (let i = 0; i < msgList.length; i++) {
                const currentMsg = msgList[i];
                const prevMsg = msgList[i - 1];
                const nextMsg = msgList[i + 1];
                const isContinuation = prevMsg && prevMsg.sender_handle === currentMsg.sender_handle && prevMsg.timestamp === currentMsg.timestamp;
                const isLastInGroup = !nextMsg || nextMsg.sender_handle !== currentMsg.sender_handle || nextMsg.timestamp !== currentMsg.timestamp;
                html += createMessageHTML(currentMsg, isContinuation, isLastInGroup);
            }
            stream.innerHTML = html;
            stream.scrollTop = stream.scrollHeight;
        }

        function renderStagedMessages() {
            const container = document.getElementById('staged-messages-container');
            container.style.display = stagedMessages.length > 0 ? 'block' : 'none';
            container.innerHTML = stagedMessages.map((msg, index) =>
                `<div class="staged-message-item" data-index="${index}">
                    <span>${msg.length > 30 ? msg.substring(0, 27) + '...' : msg}</span>
                    <button class="remove-staged-btn" data-action="remove-staged" title="移除">×</button>
                </div>`
            ).join('');
        }

        function sendCommand(messageText) {
            const command = `/send ${messageText} | /trigger await=true`;
            if (typeof triggerSlash === 'function') {
                try { triggerSlash(command); } catch (e) { alert(`指令发送失败: ${messageText}`); }
            } else { alert(`无法自动发送: ${messageText}`); }
        }

        function handleStageMessage() {
            const input = document.getElementById('composer-input');
            const content = input.value.trim();
            if (content === '') return;
            stagedMessages.push(content);
            input.value = '';
            input.focus();
            renderStagedMessages();
        }

        function handleSendAllMessages() {
            const input = document.getElementById('composer-input');
            const currentContent = input.value.trim();
            if (currentContent !== '') stagedMessages.push(currentContent);
            if (stagedMessages.length === 0) return;

            const combinedMessage = stagedMessages.join('\n');
            const commandText = `私信 ${chat_partner.handle}: ${combinedMessage}`;
            sendCommand(commandText);

            const currentTime = new Date().toLocaleTimeString('zh-CN', { hour: '2-digit', minute: '2-digit' });
            stagedMessages.forEach((msg) => {
                messages.push({ sender_handle: viewer.handle, content: msg, is_read: false, timestamp: currentTime });
            });

            renderMessages(messages);
            saveDataToLocalStorage(data);

            stagedMessages = [];
            input.value = '';
            renderStagedMessages();
        }

        function setupEventListeners() {
            document.getElementById('back-btn').addEventListener('click', () => sendCommand("返回上一页"));
            document.getElementById('stage-btn').addEventListener('click', handleStageMessage);
            document.getElementById('send-all-btn').addEventListener('click', handleSendAllMessages);
            document.getElementById('composer-input').addEventListener('keydown', (event) => {
                if ((event.ctrlKey || event.metaKey) && event.key === 'Enter') {
                    event.preventDefault();
                    handleStageMessage();
                } else if (event.key === 'Enter' && !event.shiftKey) {
                    event.preventDefault();
                    const input = document.getElementById('composer-input');
                    const content = input.value.trim();
                    if(content !== '') {
                        sendCommand(`私信 ${chat_partner.handle}: ${content}`);
                        const currentTime = new Date().toLocaleTimeString('zh-CN', { hour: '2-digit', minute: '2-digit' });
                        messages.push({ sender_handle: viewer.handle, content: content, is_read: false, timestamp: currentTime });
                        renderMessages(messages);
                        saveDataToLocalStorage(data);
                        input.value = '';
                    }
                }
            });
            document.getElementById('staged-messages-container').addEventListener('click', (event) => {
                const removeBtn = event.target.closest('[data-action="remove-staged"]');
                if (removeBtn) {
                    const item = removeBtn.parentElement;
                    const index = parseInt(item.dataset.index, 10);
                    if (!isNaN(index)) {
                        stagedMessages.splice(index, 1);
                        renderStagedMessages();
                    }
                }
            });
        }
        renderHeader(chat_partner);
        renderMessages(messages || []);
        setupEventListeners();
    });
    </script>
</body>
</html>
