        const renderUserList = (title, list) => {
            drawerTitle.textContent = title;
            if (!list || list.length === 0) {
                 drawerBody.innerHTML = `<div style="padding: 20px; text-align: center; color: var(--text-secondary);">还没有任何${title}哦</div>`;
            } else {
                 drawerBody.innerHTML = list.map(u => `
                    <div class="list-item" data-action="view-profile" data-username="${u.name}">
                        <div class="item-avatar" style="background: ${u.avatar_bg || 'linear-gradient(135deg, #88f, #f88)'}; color: white;">${u.avatar_icon || u.name.charAt(0)}</div>
                        <div class="list-item-main">
                          <div class="list-item-header"><span class="item-name">${u.name}</span></div>
                          <div class="list-item-body"><span class="last-message">${u.handle}</span></div>
                        </div>
                    </div>`).join('');
            }
            drawer.classList.add('active');
        };

        const renderMessageList = () => {
            drawerTitle.textContent = '私信';
            drawerBody.innerHTML = '<div style="padding: 20px; text-align: center; color: var(--text-secondary);">还没有任何私信哦</div>';
            drawer.classList.add('active');
        };

        const generateCommentsHTML = (postCard) => {
             const cSection = postCard.querySelector('.comment-section');
             const commentsData = JSON.parse(postCard.dataset.comments || '[]');
             let commentsHTML = commentsData.map(c => `
                <div class="comment-item">
                    <div class="comment-avatar" data-action="view-commenter-profile" data-username="${c.author}">${c.avatar}</div>
                    <div class="comment-content">
                        <div class="comment-user-info-container">
                            <span class="comment-user-name" data-action="view-commenter-profile" data-username="${c.author}">${c.author}</span>
                            <button class="comment-reply-btn" data-action="reply-to-comment" data-username="${c.author}">回复</button>
                        </div>
                        <span class="comment-text">${c.text}</span>
                    </div>
                </div>`).join('');
            cSection.innerHTML = `<div class="comments-list">${commentsHTML}</div>` + `<div class="comment-input-area"><textarea class="comment-input" placeholder="添加评论" rows="1"></textarea><button data-action="send-comment" class="comment-send-btn">发送</button></div>`;
        };

        function sendCommand(msg) {
            if (typeof triggerSlash === 'function') triggerSlash(`/send ${msg}|/trigger await=true`);
            else alert(`模拟发送: ${msg}`);
        }

        document.body.addEventListener('click', (event) => {
            const actionTarget = event.target.closest('[data-action]');
            if (!actionTarget) return;

            const action = actionTarget.dataset.action;
            const postCard = actionTarget.closest('.post-card');
            let cSection, textarea, isVisible;

            switch(action) {
                case 'go-back': sendCommand('返回首页'); break;
                case 'edit-signature':
                    const sigSpan = document.querySelector('#profile-signature span');
                    const currentSig = pageData.profile_user.signature.includes('...') ? '' : pageData.profile_user.signature;
                    const newSig = prompt('请输入新的签名:', currentSig);
                    if (newSig !== null) {
                        pageData.profile_user.signature = newSig.trim() || '一条什么都还没写的签名...';
                        sigSpan.textContent = pageData.profile_user.signature;
                    }
                    break;
                case 'view-following': renderUserList('正在关注', pageData.following_list); break;
                case 'view-followers': renderUserList('关注者', pageData.followers_list); break;
                case 'view-messages': renderMessageList(); break;
                case 'open-dm': sendCommand(`打开和 ${actionTarget.dataset.handle} 的私信`); drawer.classList.remove('active'); break;
                case 'view-profile': sendCommand(`查看用户 ${actionTarget.dataset.username} 主页`); drawer.classList.remove('active'); break;
                case 'view-commenter-profile': sendCommand(`查看用户 ${actionTarget.dataset.username} 主页`); break;
                case 'open-post-modal': newPostModal.classList.add('active'); break;
                case 'close-post-modal': newPostModal.classList.remove('active'); break;
                case 'submit-post':
                    const content = document.getElementById('post-content-input').value.trim();
                    const img = document.getElementById('post-image-input').value.trim();
                    if (!content) { alert('内容不能为空！'); return; }
                    sendCommand(`发布动态：${content}${img ? `（图片：${img}）` : ''}`);
                    newPostModal.classList.remove('active');
                    document.getElementById('post-content-input').value = '';
                    document.getElementById('post-image-input').value = '';
                    break;
                case 'delete-post':
                    const pId = postCard.dataset.postId;
                    if (confirm('确定要删除这条动态吗？')) {
                        sendCommand(`删除动态 ${pId}`);
                        postCard.remove();
                        document.getElementById('own-post-count').textContent = profileContent.children.length;
                    }
                    break;
                case 'like':
                    actionTarget.classList.toggle('liked');
                    const countEl = actionTarget.querySelector('.like-count');
                    let count = parseInt(countEl.textContent, 10);
                    countEl.textContent = actionTarget.classList.contains('liked') ? count + 1 : count - 1;
                    break;
                case 'comment-post':
                    cSection = postCard.querySelector('.comment-section');
                    if (cSection.innerHTML.trim() === '') generateCommentsHTML(postCard);
                    textarea = cSection.querySelector('textarea');
                    isVisible = getComputedStyle(cSection).display !== 'none';
                    if (isVisible && textarea.placeholder === "添加评论") {
                        cSection.style.display = 'none';
                    } else {
                        cSection.style.display = 'block';
                        textarea.placeholder = "添加评论";
                        delete textarea.dataset.replyTo;
                        textarea.focus();
                    }
                    break;
                case 'reply-to-comment':
                    cSection = postCard.querySelector('.comment-section');
                    if (cSection.innerHTML.trim() === '') generateCommentsHTML(postCard);
                    textarea = cSection.querySelector('textarea');
                    const usernameToReply = actionTarget.dataset.username;
                    cSection.style.display = 'block';
                    textarea.placeholder = `回复 ${usernameToReply}：`;
                    textarea.dataset.replyTo = usernameToReply;
                    textarea.focus();
                    break;
                case 'send-comment':
                    textarea = postCard.querySelector('textarea');
                    const commentText = textarea.value.trim();
                    if (!commentText) return;
                    const postId = postCard.dataset.postId;
                    const replyToUser = textarea.dataset.replyTo;
                    if(replyToUser) {
                        sendCommand(`在动态 ${postId} 中回复 ${replyToUser}：${commentText}`);
                    } else {
                        sendCommand(`评论动态 ${postId}：${commentText}`);
                    }
                    cSection = postCard.querySelector('.comment-section');
                    cSection.style.display = 'none';
                    break;
            }
        });
        drawer.addEventListener('click', e => { if (e.target === drawer) drawer.classList.remove('active'); });

        renderProfileHeader(pageData.profile_user);
        renderPosts(pageData.posts, pageData.profile_user);
    });
    </script>
</body>
</html>
```
